-- Impact feedback default content: metrics, the 8 catalog programs, question bank and
-- v1 templates (generated by the template engine, not hand-built per form).
-- Idempotent: existing rows are never overwritten, existing templates keep their versions.
--
-- Course-specific questions are derived from the catalog syllabi
-- (frontend/public/catalog/catalog_programs_tashpaz.json, catalog_program_ids below):
-- topics, skills and the closing products (models, posters, pitch, venture) of each program.

insert into public.feedback_metrics (key, label, kind, sort_order, description) values
  ('knowledge',      'ידע והבנה',          'impact',  10, 'הבנת התחום, המושגים והשימושים שלו'),
  ('self_efficacy',  'מסוגלות וביטחון',     'impact',  20, 'אמונה ביכולת לפתח, לחקור, להוביל ולהתנסות'),
  ('interest',       'עניין וסקרנות',       'impact',  30, 'עניין בתחום, סקרנות ומעורבות'),
  ('skills',         'מיומנויות',          'impact',  40, 'עבודת צוות, חקר, תכנון, הצגה ומיומנויות ייחודיות לתוכנית'),
  ('attitudes',      'עמדות ותפיסות',       'impact',  50, 'תפיסות לגבי מדע, טכנולוגיה, אחריות ואתיקה'),
  ('continuation',   'כוונה להמשך',         'impact',  60, 'רצון להמשיך ללמוד, להתנסות או להפעיל שוב'),
  ('satisfaction',   'חוויה ושביעות רצון',  'impact',  70, 'הנאה, השתתפות והמלצה'),
  ('overall_impact', 'השפעה כוללת',         'impact',  80, 'השפעה כוללת, השגת מטרות ושינוי שנצפה'),
  ('content',        'איכות התוכן',         'program', 110, 'איכות, בהירות, רצף, התאמה לגיל, עומס וזמן'),
  ('delivery',       'העברה בכיתה והדרכה',  'program', 120, 'ישימות הפעילויות, מקצועיות וניהול הקבוצה'),
  ('operations',     'תפעול, ציוד ותמיכה',  'program', 130, 'חומרי הדרכה, ערכות, הכשרה ותמיכה מתעשיידע')
on conflict (key) do nothing;

insert into public.feedback_programs (key, title, topic, catalog_program_ids, activity_name_patterns, exclude_patterns, default_age_band, sort_order) values
  ('biomimicry', 'ביומימיקרי – המצאות בהשראה מן הטבע', 'ביומימיקרי – המצאות בהשראת הטבע',
    array['program-01', 'program-11'], array['%ביומימיקרי%', '%ביומימקרי%'], array['%חדר בריחה%', '%הקסום%'], 'd_f', 10),
  ('green_leadership', 'מנהיגות ירוקה', 'קיימות ומנהיגות סביבתית',
    array['program-04'], array['%מנהיגות ירוקה%'], array[]::text[], 'd_f', 20),
  ('space_tech', 'טכנולוגיות החלל', 'טכנולוגיות החלל',
    array['program-03'], array['%טכנולוגיות החלל%', '%טכנולוגיות חלל%'], array[]::text[], 'd_f', 30),
  ('ai_applications', 'יישומי הבינה המלאכותית', 'יישומי בינה מלאכותית',
    array['program-10'], array['%יישומי AI%', '%AI יישומי%', '%יישומי הבינה%', '%יישומי בינה%'], array[]::text[], 'g_i', 40),
  ('pharma', 'רוקחים עולם', 'פיתוח תרופות ועולם הפרמצבטיקה',
