  ('ofek', 'אופק – יזמות פרימיום לתעשייה', 'יזמות ותעשייה',
    array['program-07'], array['%אופק%'], array[]::text[], 'g_i', 60),
  ('ai_foundations', 'סודות ויסודות הבינה המלאכותית', 'בינה מלאכותית',
