-- Question bank. Fields: key, program (null = core), metric, type, audiences, stages,
-- comparison (same concept asked in PRE and POST), sort, required, wording (age variants:
-- a_c = א׳–ג׳, d_f = ד׳–ו׳, g_i = ז׳–ט׳, j_l = י׳–י״ב, default = fallback), options, scoring.
insert into public.feedback_questions (
  question_key, program_key, metric_key, question_type, audiences, stages, is_comparison,
  sort_order, default_required, wording, options, scoring
)
select q.key, q.program, q.metric, q.type, q.audiences, q.stages, coalesce(q.comparison, false),
  q.sort, coalesce(q.required, true), q.wording, coalesce(q.options, '[]'::jsonb),
  coalesce(q.scoring, case when q.type = 'rating_1_5' then '{"include_in_score": true}'::jsonb else '{"include_in_score": false}'::jsonb end)
from jsonb_to_recordset($json$[
  {"key":"s_core_knowledge","metric":"knowledge","type":"rating_1_5","audiences":["student"],"stages":["pre","post"],"comparison":true,"sort":10,
   "wording":{"default":"אני מבין/ה מה לומדים בתחום {topic} ואיך משתמשים בו בעולם האמיתי","a_c":"אני יודע/ת מה זה {topic}","j_l":"אני מבין/ה את העקרונות של התחום {topic} ואת השימושים שלו בעולם האמיתי"}},
  {"key":"s_core_efficacy","metric":"self_efficacy","type":"rating_1_5","audiences":["student"],"stages":["pre","post"],"comparison":true,"sort":20,
   "wording":{"default":"אני מאמין/ה שאני מסוגל/ת לפתח רעיון לפתרון של בעיה אמיתית","a_c":"אני יכול/ה להמציא פתרון לבעיה"}},
  {"key":"s_core_interest","metric":"interest","type":"rating_1_5","audiences":["student"],"stages":["pre","post"],"comparison":true,"sort":30,
   "wording":{"default":"התחום של {topic} מעניין אותי","a_c":"{topic} – זה מעניין אותי"}},
  {"key":"s_core_curiosity","metric":"interest","type":"rating_1_5","audiences":["student"],"stages":["pre","post"],"comparison":true,"sort":40,
   "wording":{"default":"אני אוהב/ת לשאול שאלות ולחקור איך דברים עובדים","a_c":"אני אוהב/ת לגלות איך דברים עובדים"}},
  {"key":"s_core_teamwork","metric":"skills","type":"rating_1_5","audiences":["student"],"stages":["pre","post"],"comparison":true,"sort":50,
   "wording":{"default":"אני יודע/ת לעבוד בצוות כדי לפתח רעיון משותף","a_c":"אני יודע/ת לעבוד יחד עם חברים על משימה"}},
  {"key":"s_core_attitude","metric":"attitudes","type":"rating_1_5","audiences":["student"],"stages":["pre","post"],"comparison":true,"sort":60,
   "wording":{"default":"אני חושב/ת שמדע וטכנולוגיה יכולים לעזור לפתור בעיות אמיתיות בעולם","a_c":"מדע וטכנולוגיה עוזרים לאנשים"}},
  {"key":"s_core_continuation","metric":"continuation","type":"rating_1_5","audiences":["student"],"stages":["pre","post"],"comparison":true,"sort":70,
   "wording":{"default":"הייתי רוצה להמשיך ללמוד ולהתנסות בתחום {topic} גם בעתיד","a_c":"הייתי רוצה ללמוד עוד על {topic}"}},

  {"key":"s_post_enjoy","metric":"satisfaction","type":"rating_1_5","audiences":["student"],"stages":["post"],"sort":210,
   "wording":{"default":"הפעילויות בתוכנית היו מעניינות","a_c":"נהניתי בפעילויות"}},
  {"key":"s_post_participation","metric":"satisfaction","type":"rating_1_5","audiences":["student"],"stages":["post"],"sort":220,
   "wording":{"default":"השתתפתי באופן פעיל במפגשים","a_c":"השתתפתי בפעילויות"}},
  {"key":"s_post_learning","metric":"knowledge","type":"rating_1_5","audiences":["student"],"stages":["post"],"sort":230,
   "wording":{"default":"הרגשתי שלמדתי בתוכנית דברים חדשים וחשובים","a_c":"למדתי דברים חדשים"}},
  {"key":"s_post_confidence","metric":"self_efficacy","type":"rating_1_5","audiences":["student"],"stages":["post"],"sort":240,
   "wording":{"default":"אחרי התוכנית אני מרגיש/ה בטוח/ה יותר להתנסות – לבנות, לחקור ולהמציא בעצמי","a_c":"עכשיו אני מרגיש/ה שאני יכול/ה לבנות ולהמציא בעצמי"}},
  {"key":"s_post_recommend","metric":"satisfaction","type":"rating_1_5","audiences":["student"],"stages":["post"],"sort":250,
   "wording":{"default":"הייתי ממליץ/ה לחברים להשתתף בתוכנית","a_c":"הייתי רוצה שגם חברים שלי ישתתפו"}},
  {"key":"s_post_overall","metric":"overall_impact","type":"rating_1_5","audiences":["student"],"stages":["post"],"sort":260,
   "wording":{"default":"התוכנית השפיעה עליי ושינתה את הדרך שבה אני חושב/ת על התחום","a_c":"התוכנית לימדה אותי משהו שאזכור"}},
  {"key":"s_post_open_like","metric":"satisfaction","type":"free_text","audiences":["student"],"stages":["post"],"sort":910,"required":false,
   "wording":{"default":"מה הכי אהבת בתוכנית?"}},
  {"key":"s_post_open_change","metric":"satisfaction","type":"free_text","audiences":["student"],"stages":["post"],"sort":920,"required":false,
   "wording":{"default":"מה היית משנה או משפר/ת בתוכנית?"}},

  {"key":"st_age_fit","metric":"content","type":"rating_1_5","audiences":["educational_staff"],"stages":["final"],"sort":10,
   "wording":{"default":"התוכנית הותאמה לגיל ולרמת התלמידים"}},
  {"key":"st_content_quality","metric":"content","type":"rating_1_5","audiences":["educational_staff"],"stages":["final"],"sort":20,
   "wording":{"default":"התוכן המקצועי של התוכנית איכותי ורלוונטי"}},
  {"key":"st_engagement","metric":"interest","type":"rating_1_5","audiences":["educational_staff"],"stages":["final"],"sort":30,
   "wording":{"default":"התלמידים גילו מעורבות והשתתפות פעילה במפגשים"}},
  {"key":"st_knowledge","metric":"knowledge","type":"rating_1_5","audiences":["educational_staff"],"stages":["final"],"sort":40,
   "wording":{"default":"התלמידים רכשו ידע חדש ומשמעותי בתחום {topic}"}},
  {"key":"st_efficacy","metric":"self_efficacy","type":"rating_1_5","audiences":["educational_staff"],"stages":["final"],"sort":50,
   "wording":{"default":"ניכר שהתלמידים מרגישים מסוגלים יותר לפתח רעיונות ופתרונות"}},
  {"key":"st_curiosity","metric":"interest","type":"rating_1_5","audiences":["educational_staff"],"stages":["final"],"sort":60,
   "wording":{"default":"התוכנית עוררה אצל התלמידים סקרנות ורצון לחקור"}},
  {"key":"st_creative","metric":"skills","type":"rating_1_5","audiences":["educational_staff"],"stages":["final"],"sort":70,
   "wording":{"default":"התוכנית פיתחה אצל התלמידים חשיבה יצירתית"}},
  {"key":"st_problem_solving","metric":"skills","type":"rating_1_5","audiences":["educational_staff"],"stages":["final"],"sort":80,
   "wording":{"default":"התוכנית פיתחה אצל התלמידים יכולת פתרון בעיות"}},
  {"key":"st_teamwork","metric":"skills","type":"rating_1_5","audiences":["educational_staff"],"stages":["final"],"sort":90,
   "wording":{"default":"התוכנית חיזקה את העבודה בצוות בין התלמידים"}},
  {"key":"st_change","metric":"overall_impact","type":"rating_1_5","audiences":["educational_staff"],"stages":["final"],"sort":100,
   "wording":{"default":"הבחנו בשינוי חיובי אצל התלמידים לאורך התוכנית"}},
  {"key":"st_instructor_prof","metric":"delivery","type":"rating_1_5","audiences":["educational_staff"],"stages":["final"],"sort":110,
   "wording":{"default":"המדריך/ה הפגין/ה מקצועיות וידע"}},
  {"key":"st_group_mgmt","metric":"delivery","type":"rating_1_5","audiences":["educational_staff"],"stages":["final"],"sort":120,
   "wording":{"default":"המדריך/ה ניהל/ה את הקבוצה היטב"}},
  {"key":"st_rapport","metric":"delivery","type":"rating_1_5","audiences":["educational_staff"],"stages":["final"],"sort":130,
   "wording":{"default":"המדריך/ה יצר/ה קשר טוב עם התלמידים"}},
  {"key":"st_again","metric":"continuation","type":"yes_no","audiences":["educational_staff"],"stages":["final"],"sort":140,
   "wording":{"default":"הייתם רוצים להפעיל את התוכנית שוב?"},
   "scoring":{"include_in_score":true,"yes":5,"no":1}},
  {"key":"st_change_areas","metric":"overall_impact","type":"multi_select","audiences":["educational_staff"],"stages":["final"],"sort":800,"required":false,
   "wording":{"default":"באילו תחומים הבחנתם בשינוי אצל התלמידים?"},
   "options":[{"value":"knowledge","label":"ידע והבנה"},{"value":"self_efficacy","label":"מסוגלות וביטחון"},{"value":"interest","label":"עניין וסקרנות"},{"value":"skills","label":"מיומנויות (חשיבה יצירתית, פתרון בעיות, עבודת צוות)"},{"value":"attitudes","label":"עמדות ותפיסות"},{"value":"continuation","label":"רצון להמשיך בתחום"},{"value":"none","label":"לא הבחנו בשינוי משמעותי"}]},
  {"key":"st_open_comments","metric":"satisfaction","type":"free_text","audiences":["educational_staff"],"stages":["final"],"sort":900,"required":false,
   "wording":{"default":"הערות, הצעות או דברים נוספים שחשוב לכם לשתף"}},

  {"key":"in_content_quality","metric":"content","type":"rating_1_5","audiences":["instructor"],"stages":["final"],"sort":10,
   "wording":{"default":"התוכן המקצועי של התוכנית איכותי"}},
  {"key":"in_clarity","metric":"content","type":"rating_1_5","audiences":["instructor"],"stages":["final"],"sort":20,
   "wording":{"default":"התוכן ברור ומובנה"}},
  {"key":"in_sequence","metric":"content","type":"rating_1_5","audiences":["instructor"],"stages":["final"],"sort":30,
   "wording":{"default":"רצף המפגשים הגיוני ובונה למידה מדורגת"}},
  {"key":"in_age_fit","metric":"content","type":"rating_1_5","audiences":["instructor"],"stages":["final"],"sort":40,
   "wording":{"default":"התוכן מותאם לגיל התלמידים"}},
  {"key":"in_load","metric":"content","type":"single_select","audiences":["instructor"],"stages":["final"],"sort":50,
   "wording":{"default":"איך היית מתאר/ת את רמת העומס של התוכן?"},
   "options":[{"value":"too_light","label":"דל מדי"},{"value":"balanced","label":"מאוזן"},{"value":"too_heavy","label":"עמוס מדי"}]},
  {"key":"in_time_fit","metric":"content","type":"single_select","audiences":["instructor"],"stages":["final"],"sort":60,
   "wording":{"default":"האם הזמן שהוקצה למפגשים התאים לתוכן?"},
   "options":[{"value":"not_enough","label":"הזמן לא הספיק"},{"value":"fits","label":"הזמן התאים"},{"value":"too_much","label":"נשאר זמן מיותר"}]},
  {"key":"in_ease","metric":"delivery","type":"rating_1_5","audiences":["instructor"],"stages":["final"],"sort":70,
   "wording":{"default":"קל להעביר את התוכן בכיתה"}},
  {"key":"in_activities_worked","metric":"delivery","type":"rating_1_5","audiences":["instructor"],"stages":["final"],"sort":80,
   "wording":{"default":"הפעילויות עבדו בפועל בכיתה כפי שתוכננו"}},
  {"key":"in_materials","metric":"operations","type":"rating_1_5","audiences":["instructor"],"stages":["final"],"sort":90,
   "wording":{"default":"חומרי ההדרכה (מערכים, מצגות) מספקים ונוחים לעבודה"}},
  {"key":"in_kits","metric":"operations","type":"rating_1_5","audiences":["instructor"],"stages":["final"],"sort":100,
   "wording":{"default":"הערכות והציוד היו מתאימים, תקינים וזמינים"}},
  {"key":"in_engagement","metric":"interest","type":"rating_1_5","audiences":["instructor"],"stages":["final"],"sort":110,
   "wording":{"default":"התלמידים היו מעורבים ומשתתפים לאורך הקורס"}},
  {"key":"in_goals","metric":"overall_impact","type":"rating_1_5","audiences":["instructor"],"stages":["final"],"sort":120,
   "wording":{"default":"מטרות הקורס הושגו"}},
  {"key":"in_support","metric":"operations","type":"rating_1_5","audiences":["instructor"],"stages":["final"],"sort":130,
   "wording":{"default":"התפעול והתמיכה מצד תעשיידע היו טובים"}},
  {"key":"in_training","metric":"operations","type":"rating_1_5","audiences":["instructor"],"stages":["final"],"sort":140,
   "wording":{"default":"ההכשרה שקיבלתי לקראת התוכנית הכינה אותי היטב"}},
  {"key":"in_again","metric":"continuation","type":"rating_1_5","audiences":["instructor"],"stages":["final"],"sort":150,
   "wording":{"default":"הייתי רוצה להדריך את התוכנית שוב"}},
  {"key":"in_open_best","metric":"content","type":"free_text","audiences":["instructor"],"stages":["final"],"sort":910,"required":false,
   "wording":{"default":"איזה חלק בתוכנית עבד הכי טוב?"}},
  {"key":"in_open_change","metric":"content","type":"free_text","audiences":["instructor"],"stages":["final"],"sort":920,"required":false,
   "wording":{"default":"איזה חלק בתוכן היית משנה?"}},
  {"key":"in_open_missing","metric":"content","type":"free_text","audiences":["instructor"],"stages":["final"],"sort":930,"required":false,
   "wording":{"default":"מה חסר בתוכנית?"}},
  {"key":"in_open_differently","metric":"delivery","type":"free_text","audiences":["instructor"],"stages":["final"],"sort":940,"required":false,
   "wording":{"default":"אם היית מעביר/ה את התוכנית שוב, מה היית עושה אחרת?"}}
]$json$::jsonb) as q(
  key text, program text, metric text, type text, audiences text[], stages text[], comparison boolean,
  sort int, required boolean, wording jsonb, options jsonb, scoring jsonb
)
on conflict (question_key) do nothing;

-- Course-specific questions (3–5 per program), grounded in each catalog syllabus.
insert into public.feedback_questions (
  question_key, program_key, metric_key, question_type, audiences, stages, is_comparison,
  sort_order, default_required, wording, options, scoring
)
select q.key, q.program, q.metric, 'rating_1_5', q.audiences, q.stages, coalesce(q.comparison, false),
  q.sort, true, q.wording, '[]'::jsonb, '{"include_in_score": true}'::jsonb
from jsonb_to_recordset($json$[
  {"key":"biomimicry_example","program":"biomimicry","metric":"knowledge","audiences":["student"],"stages":["pre","post"],"comparison":true,"sort":100,
   "wording":{"default":"אני יכול/ה לתת דוגמה להמצאה או לפתרון טכנולוגי שנוצרו בהשראת הטבע","a_c":"אני מכיר/ה המצאה שנוצרה בהשראת הטבע"}},
  {"key":"biomimicry_research","program":"biomimicry","metric":"skills","audiences":["student"],"stages":["pre","post"],"comparison":true,"sort":110,
   "wording":{"default":"אני יודע/ת לחקור מנגנון בטבע ולהסביר איך אפשר להיעזר בו כדי לפתור בעיה","a_c":"כשאני מסתכל/ת על הטבע, אני יכול/ה למצוא בו רעיונות להמצאות"}},
  {"key":"biomimicry_product","program":"biomimicry","metric":"overall_impact","audiences":["student"],"stages":["post"],"sort":300,
   "wording":{"default":"אני גאה בדגם או בפוסטר שפיתחנו בהשראת הטבע","a_c":"אני גאה בדגם שבנינו"}},
  {"key":"biomimicry_staff","program":"biomimicry","metric":"knowledge","audiences":["educational_staff"],"stages":["final"],"sort":500,
   "wording":{"default":"התלמידים הצליחו לקשר בין מנגנונים בטבע לבין פתרונות טכנולוגיים"}},
  {"key":"biomimicry_instructor","program":"biomimicry","metric":"overall_impact","audiences":["instructor"],"stages":["final"],"sort":500,
